/bin/bash -lc "node --input-type=module <<'NODE'
import { createServer } from 'node:http'
import { spawn } from 'node:child_process'
import { setTimeout as delay } from 'node:timers/promises'

const events = []
const analytics = createServer(async (req, res) => {
  let body = ''
  for await (const chunk of req) body += chunk
  events.push(JSON.parse(body))
  await delay(2000)
  res.writeHead(204).end()
})
await new Promise(resolve => analytics.listen(0, '127.0.0.1', resolve))
const endpoint = "'`http://127.0.0.1:${analytics.address().port}/events`
const app = spawn('"'node_modules/.bin/next', ['start', '-p', '3149'], {
  env: { ...process.env, ANALYTICS_ENDPOINT: endpoint },
  stdio: ['ignore', 'pipe', 'pipe'],
})
let output = ''
app.stdout.on('data', chunk => output += chunk)
app.stderr.on('data', chunk => output += chunk)
try {
  for (let i = 0; i < 100 && "'!output.includes('"'Ready'); i++) {
    if (app.exitCode "'!== null) throw new Error(`Next exited: ${output}`)
    await delay(100)
  }
  if (!output.includes('"'Ready')) throw new Error("'`Next did not start: ${output}`)
  for (let i = 0; i < 2; i++) {
    const start = performance.now()
    const response = await fetch('"'http://127.0.0.1:3149/')
    const body = await response.text()
    const elapsed = Math.round(performance.now() - start)
    if ("'!response.ok || !body.includes('"'Welcome')) throw new Error('Welcome page failed')
    if (elapsed >= 1500) throw new Error("'`Page waited for analytics: ${elapsed}ms`)
    console.log(`Request ${i + 1}: HTTP ${response.status}, welcome rendered, ${elapsed}ms`)
  }
  for (let i = 0; i < 50 && events.length < 2; i++) await delay(100)
  if (events.length !== 2 || events.some(e => e.event !== '"'page_view' || e.path "'!== '"'/')) {
    throw new Error("'`Unexpected analytics events: ${JSON.stringify(events)}`)
  }
  console.log(`Analytics received ${events.length} page_view events; each response is delayed 2000ms`)
} finally {
  app.kill('"'SIGTERM')
  analytics.closeAllConnections()
  analytics.close()
}
NODE"

